; T2.PLM's procedures P2BB ... P5 as Intel's PL/M-80 V3.1 compiled them:
; T2.LST, statements 4 to 69, transcribed instruction for instruction in
; 8080 mnemonics.  Only the addresses are symbolic.  Each procedure's
; parameters are consecutive bytes, first to last, as PL/M-80 laid them
; out, since its entry stores them from the last down with DCX H.
; The module's variables B1 ... A5 are EXTRN here: the test's PL/M
; module defines them.

	PUBLIC	P2BB,P2AA,P2AB,P2BA,P3BBB,P3AAA,P3BAB,P3ABA,P4,P4X,P5
	EXTRN	B1,B2,B3,B4,B5,A1,A2,A3,A4,A5
	CSEG

; P2BB: PROCEDURE(X, Y) PUBLIC; DECLARE (X, Y) BYTE; B1 = X; B2 = Y; END P2BB;
P2BB:	LXI	H,P2BBY
	MOV	M,E
	DCX	H
	MOV	M,C
	LDA	P2BBX
	STA	B1
	LDA	P2BBY
	STA	B2
	RET

; P2AA: PROCEDURE(X, Y) PUBLIC; DECLARE (X, Y) ADDRESS; A1 = X; A2 = Y; END P2AA;
P2AA:	LXI	H,P2AAY+1H
	MOV	M,D
	DCX	H
	MOV	M,E
	DCX	H
	MOV	M,B
	DCX	H
	MOV	M,C
	LHLD	P2AAX
	SHLD	A1
	LHLD	P2AAY
	SHLD	A2
	RET

; P2AB: PROCEDURE(X, Y) PUBLIC; DECLARE X ADDRESS, Y BYTE; A1 = X; B2 = Y; END P2AB;
P2AB:	LXI	H,P2ABY
	MOV	M,E
	DCX	H
	MOV	M,B
	DCX	H
	MOV	M,C
	LHLD	P2ABX
	SHLD	A1
	LDA	P2ABY
	STA	B2
	RET

; P2BA: PROCEDURE(X, Y) PUBLIC; DECLARE X BYTE, Y ADDRESS; B1 = X; A2 = Y; END P2BA;
P2BA:	LXI	H,P2BAY+1H
	MOV	M,D
	DCX	H
	MOV	M,E
	DCX	H
	MOV	M,C
	LDA	P2BAX
	STA	B1
	LHLD	P2BAY
	SHLD	A2
	RET

; P3BBB: PROCEDURE(X, Y, Z) PUBLIC; DECLARE (X, Y, Z) BYTE;
;   B1 = X; B2 = Y; B3 = Z; END P3BBB;
P3BBB:	LXI	H,P3BBBZ
	MOV	M,E
	DCX	H
	MOV	M,C
	DCX	H
	POP	D
	POP	B
	MOV	M,C
	PUSH	D
	LDA	P3BBBX
	STA	B1
	LDA	P3BBBY
	STA	B2
	LDA	P3BBBZ
	STA	B3
	RET

; P3AAA: PROCEDURE(X, Y, Z) PUBLIC; DECLARE (X, Y, Z) ADDRESS;
;   A1 = X; A2 = Y; A3 = Z; END P3AAA;
P3AAA:	LXI	H,P3AAAZ+1H
	MOV	M,D
	DCX	H
	MOV	M,E
	DCX	H
	MOV	M,B
	DCX	H
	MOV	M,C
	DCX	H
	POP	D
	POP	B
	MOV	M,B
	DCX	H
	MOV	M,C
	PUSH	D
	LHLD	P3AAAX
	SHLD	A1
	LHLD	P3AAAY
	SHLD	A2
	LHLD	P3AAAZ
	SHLD	A3
	RET

; P3BAB: PROCEDURE(X, Y, Z) PUBLIC; DECLARE (X, Z) BYTE, Y ADDRESS;
;   B1 = X; A2 = Y; B3 = Z; END P3BAB;
P3BAB:	LXI	H,P3BABZ
	MOV	M,E
	DCX	H
	MOV	M,B
	DCX	H
	MOV	M,C
	DCX	H
	POP	D
	POP	B
	MOV	M,C
	PUSH	D
	LDA	P3BABX
	STA	B1
	LHLD	P3BABY
	SHLD	A2
	LDA	P3BABZ
	STA	B3
	RET

; P3ABA: PROCEDURE(X, Y, Z) PUBLIC; DECLARE (X, Z) ADDRESS, Y BYTE;
;   A1 = X; B2 = Y; A3 = Z; END P3ABA;
P3ABA:	LXI	H,P3ABAZ+1H
	MOV	M,D
	DCX	H
	MOV	M,E
	DCX	H
	MOV	M,C
	DCX	H
	POP	D
	POP	B
	MOV	M,B
	DCX	H
	MOV	M,C
	PUSH	D
	LHLD	P3ABAX
	SHLD	A1
	LDA	P3ABAY
	STA	B2
	LHLD	P3ABAZ
	SHLD	A3
	RET

; P4: PROCEDURE(W, X, Y, Z) PUBLIC; DECLARE (W, Y) BYTE, (X, Z) ADDRESS;
;   B1 = W; A2 = X; B3 = Y; A4 = Z; END P4;
P4:	LXI	H,P4Z+1H
	MOV	M,D
	DCX	H
	MOV	M,E
	DCX	H
	MOV	M,C
	DCX	H
	POP	D
	POP	B
	MOV	M,B
	DCX	H
	MOV	M,C
	DCX	H
	POP	B
	MOV	M,C
	PUSH	D
	LDA	P4W
	STA	B1
	LHLD	P4X_
	SHLD	A2
	LDA	P4Y
	STA	B3
	LHLD	P4Z
	SHLD	A4
	RET

; P4X: PROCEDURE(W, X, Y, Z) PUBLIC; DECLARE (W, Y) ADDRESS, (X, Z) BYTE;
;   A1 = W; B2 = X; A3 = Y; B4 = Z; END P4X;
P4X:	LXI	H,P4XZ
	MOV	M,E
	DCX	H
	MOV	M,B
	DCX	H
	MOV	M,C
	DCX	H
	POP	D
	POP	B
	MOV	M,C
	DCX	H
	POP	B
	MOV	M,B
	DCX	H
	MOV	M,C
	PUSH	D
	LHLD	P4XW
	SHLD	A1
	LDA	P4XX
	STA	B2
	LHLD	P4XY
	SHLD	A3
	LDA	P4XZ
	STA	B4
	RET

; P5: PROCEDURE(V, W, X, Y, Z) PUBLIC; DECLARE (V, X, Z) BYTE, (W, Y) ADDRESS;
;   B1 = V; A2 = W; B3 = X; A4 = Y; B5 = Z; END P5;
P5:	LXI	H,P5Z
	MOV	M,E
	DCX	H
	MOV	M,B
	DCX	H
	MOV	M,C
	DCX	H
	POP	D
	POP	B
	MOV	M,C
	DCX	H
	POP	B
	MOV	M,B
	DCX	H
	MOV	M,C
	DCX	H
	POP	B
	MOV	M,C
	PUSH	D
	LDA	P5V
	STA	B1
	LHLD	P5W
	SHLD	A2
	LDA	P5X
	STA	B3
	LHLD	P5Y
	SHLD	A4
	LDA	P5Z
	STA	B5
	RET

	DSEG
P2BBX:	DS	1
P2BBY:	DS	1
P2AAX:	DS	2
P2AAY:	DS	2
P2ABX:	DS	2
P2ABY:	DS	1
P2BAX:	DS	1
P2BAY:	DS	2
P3BBBX:	DS	1
P3BBBY:	DS	1
P3BBBZ:	DS	1
P3AAAX:	DS	2
P3AAAY:	DS	2
P3AAAZ:	DS	2
P3BABX:	DS	1
P3BABY:	DS	2
P3BABZ:	DS	1
P3ABAX:	DS	2
P3ABAY:	DS	1
P3ABAZ:	DS	2
P4W:	DS	1
P4X_:	DS	2
P4Y:	DS	1
P4Z:	DS	2
P4XW:	DS	2
P4XX:	DS	1
P4XY:	DS	2
P4XZ:	DS	1
P5V:	DS	1
P5W:	DS	2
P5X:	DS	1
P5Y:	DS	2
P5Z:	DS	1
	END
